const STORE_KEY        = '\x6d\x67\x2e\x70\x72\x6f\x64\x75\x63\x74\x73\x2e\x76\x31';
const DELETED_PROD_KEY = '\x6d\x67\x2e\x70\x72\x6f\x64\x75\x63\x74\x73\x2e\x64\x65\x6c\x65\x74\x65\x64\x2e\x76\x31';
const EDITED_PROD_KEY  = '\x6d\x67\x2e\x70\x72\x6f\x64\x75\x63\x74\x73\x2e\x65\x64\x69\x74\x65\x64\x2e\x76\x31';
const FAV_KEY          = '\x6d\x67\x2e\x77\x69\x73\x68\x6c\x69\x73\x74\x2e\x76\x31';
const CART_KEY         = '\x6d\x67\x2e\x63\x61\x72\x74\x2e\x76\x31';
const ORDERS_KEY       = '\x6d\x67\x2e\x6f\x72\x64\x65\x72\x73\x2e\x76\x31';
const RECENT_KEY       = '\x6d\x67\x2e\x72\x65\x63\x65\x6e\x74\x2e\x76\x31';
function readStore(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : fallback;
  } catch (e) {
    return fallback;
  }
}
function writeStore(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch (e) {
    return false;
  }
}
function getDeletedProductIds() {
  return readStore(DELETED_PROD_KEY, []);
}
function getEditedProducts() {
  return readStore(EDITED_PROD_KEY, {});
}
function allProducts() {
  const deletedSet = new Set(getDeletedProductIds());
  const edits = getEditedProducts();
  const custom = readStore(STORE_KEY, []).filter(p => !deletedSet.has(p.id)).map(p => {
    return edits[p.id] ? { ...p, ...edits[p.id] } : p;
  });
  const base = LISTINGS.filter(p => !deletedSet.has(p.id)).map(p => {
    return edits[p.id] ? { ...p, ...edits[p.id] } : p;
  });
  return [...custom, ...base];
}
function deleteAnyProduct(id) {
  const deleted = getDeletedProductIds();
  if (!deleted.includes(id)) {
    deleted.push(id);
    writeStore(DELETED_PROD_KEY, deleted);
  }
  const added = readStore(STORE_KEY, []).filter(p => p.id !== id);
  writeStore(STORE_KEY, added);
  return true;
}
function updateAnyProduct(product) {
  const edits = getEditedProducts();
  edits[product.id] = product;
  writeStore(EDITED_PROD_KEY, edits);
  const added = readStore(STORE_KEY, []);
  const idx = added.findIndex(p => p.id === product.id);
  if (idx > -1) {
    added[idx] = product;
    writeStore(STORE_KEY, added);
  }
  return true;
}
function decrementLocalStock(lines) {
  if (!Array.isArray(lines) || !lines.length) return;
  const edits = getEditedProducts();
  const customProds = readStore(STORE_KEY, []);
  let customChanged = false;
  lines.forEach(l => {
    const prod = productById(l.id);
    if (prod) {
      const currentStock = Number(prod.stock !== undefined ? prod.stock : 0);
      const qty = Math.max(1, Number(l.qty || 1));
      const newStock = Math.max(0, currentStock - qty);
      edits[prod.id] = { ...prod, stock: newStock };
      const cIdx = customProds.findIndex(p => p.id === prod.id);
      if (cIdx > -1) {
        customProds[cIdx] = { ...customProds[cIdx], stock: newStock };
        customChanged = true;
      }
    }
  });
  writeStore(EDITED_PROD_KEY, edits);
  if (customChanged) writeStore(STORE_KEY, customProds);
}
function productById(id) {
  if (!id) return null;
  const cleanId = String(id).trim();
  return allProducts().find(p => p.id === id || String(p.id).trim() === cleanId) || null;
}
function getOrders() {
  const raw = readStore(ORDERS_KEY, []);
  return Array.isArray(raw) ? raw : [];
}
function orderDate(iso) {
  const d = new Date(iso);
  if (isNaN(d)) return '\u2014';
  return d.toLocaleString('\x65\x6e\x2d\x47\x42', {
    day: '\x6e\x75\x6d\x65\x72\x69\x63', month: '\x73\x68\x6f\x72\x74', year: '\x6e\x75\x6d\x65\x72\x69\x63',
    hour: '\x6e\x75\x6d\x65\x72\x69\x63', minute: '\x32\x2d\x64\x69\x67\x69\x74', hour12: true
  });
}
const ORDER_STAGES = ['\x50\x65\x6e\x64\x69\x6e\x67', '\x43\x6f\x6e\x66\x69\x72\x6d\x65\x64', '\x44\x65\x6c\x69\x76\x65\x72\x65\x64'];
function orderStage(order) {
  if (order && order.status) {
    const s = String(order.status).trim();
    if (s.toLowerCase() === '\x63\x61\x6e\x63\x65\x6c' || s.toLowerCase() === '\x63\x61\x6e\x63\x65\x6c\x6c\x65\x64') return '\x43\x61\x6e\x63\x65\x6c\x6c\x65\x64';
    const match = ORDER_STAGES.find(st => st.toLowerCase() === s.toLowerCase());
    if (match) return match;
  }
  const days = (Date.now() - new Date(order.placedAt).getTime()) / 86400000;
  if (isNaN(days)) return ORDER_STAGES[0];
  return ORDER_STAGES[Math.min(Math.floor(days), ORDER_STAGES.length - 1)];
}
function pushRecent(id) {
  const list = readStore(RECENT_KEY, []).filter(x => x !== id);
  list.unshift(id);
  writeStore(RECENT_KEY, list.slice(0, 8));
}
function getRecent() {
  return readStore(RECENT_KEY, [])
    .map(productById)
    .filter(Boolean);
}